     "id": "tasks-194",
     "n": 194,
     "kind": "fix",
     "title": "משימות מסיכום פגישה: נוצרות היום מיד וללא קשר לפעולה בסיכום — צריך ליצור רק באישור, מצב אחד לשני המסכים, ושיוך לפי \"באחריות\"",
     "what": "בסטייג׳ינג 06.09, פגישה 471 (ניולדג׳ בע\"מ, 09.08, הסיכום \"ממתין לאישור\"): השרת כבר יצר ממנה משימות ב-04.09 07:02Z (למשל משימה 6 \"קביעת פגישה הבאה לאחר קבלת הנתונים הראשוניים\", source=meeting) — למרות שבטאב \"משימות\" של הפגישה הפעולות עדיין מחכות ל\"אישור\" (\"יש לאשרן, ורק לאחר מכן ליצור את המשימות\"). אייל סימן את משימה 6 \"בוצע\" במסך המשימות (done_at נשמר) — ובפגישה הפעולה לא השתנתה, כי הפעולה בסיכום היא רשומה בתוך ה-JSON של הסיכום בלי מזהה משימה ובלי מצב. גם השיוך שגוי: פעולות שבאחריות הלקוח (\"באחריות: ניולדג׳ בע\"מ\") נכנסו לרשימת המשימות של היועץ.\n\nמדויק (06.09 11:15): יש שתי טבלאות. (א) פעולות הפגישה — GET /api/tasks/471 מחזיר 3 שורות עם id משלהן ומצב: 1522 \"איסוף וריכוז דוחות…\" suggested, 1523 \"הכנת רשימת כלל המערכות…\" suggested, 1524 \"קביעת פגישה הבאה…\" approved (אייל אישר עכשיו בטאב של הפגישה), owner = טקסט חופשי (\"ניולדג׳ בע\"מ\", \"יועץ וניולדג׳ בע\"מ\"). (ב) משימות היועץ — GET /api/workspace/advisor/tasks: משימה 6 היא עותק של 1524 (source=meeting, meeting_id=471) עם done_at משלה, בלי מזהה של 1524. שני העותקים, שני מצבים, בלי קשר ביניהם.",
     "need": "הכרעות אייל 06.09:\n1. משימה מפעולה בסיכום נוצרת רק כשמאשרים את הפעולה בטאב \"משימות\" של הפגישה (או את הסיכום כולו) — לא כשהסיכום מוכן. משימות שכבר נוצרו מסיכומים שלא אושרו — למחוק.\n2. רשומה אחת, לא עותק: עדיף שהפעולה בפגישה היא עצמה המשימה (טבלת המשימות עם meeting_id + מזהה הפעולה, והטאב \"משימות\" בפגישה קורא משם). אם נשארות שתי טבלאות — קישור מזהה (6 → 1524) ומצב אחד; \"בוצע\" במסך המשימות = בוצע בפגישה, ולהפך. הטאב בפגישה מציג את מצב המשימה עצמה.\n3. שיוך לפי השדה \"באחריות\" של הפעולה: \"יועץ\" → משימה של היועץ (המשימות שלי); \"מנהל תזרים\" או השם של מנהל התזרים → משימה של מנהל התזרים (התור שלו); שם הלקוח → משימה של הלקוח (הדשבורד שלו), לא ברשימת היועץ. \"יועץ וניולדג׳\" (שניהם) → אצל היועץ.\nבדיקה: לאשר פעולה אחת בפגישה 471 → נוצרת בדיוק משימה אחת אצל מי שרשום ב\"באחריות\"; לסמן אותה \"בוצע\" במסך המשימות → בפגישה מסומנת; לסמן בפגישה → במסך המשימות מסומנת. פעולה שלא אושרה — אין לה משימה.\n\n4. אין משימת \"תיאום מחדש\" (אייל 06.09): לא ליצור kind=reschedule בכלל, ולמחוק את הקיימות (משימות 3 ו-5 של advisor:rep). \"לא התקיימה\" נשאר רק במסך הפגישות (\"לתאם עכשיו\").",
