     "id": "company-meetings-106",
     "n": 106,
     "kind": "check",
     "title": "למזג ‎PR #7‎ — פגישות בכרטיס החברה: הזירה, הציר, שני הפופאפים ותצוגת בעל העסק",
     "what": "https://github.com/h-beehive/hk-client/pull/7 — ענף design/company-meetings אל stg, עצמאי (לא תלוי ב-PR אחר). שני קומיטים: (1) תצוגת בעל העסק — שלושה מצבים, בלי שיחות; (2) כל המסך לפי docs/cli/meetings.html: ראש הזירה הנייבי (יום·תאריך, שעה 31px, צ׳יפ מצב, שם, משתתף, נגן-גלולה), הציר (כותרת+ספירה, מקצב, קבוצות עם חץ וסיכום מקופל, ארבעה גווני נקודה, סמן \"עכשיו\"), טאבים עם קו קורל, פס העיבוד, רשימת המשימות, הפוטרים (יועץ / אחרי אישור / בעל העסק), פגישה עתידית ולא-התקיימה, פופאפ הנמענים (420px) ותיאום פגישה מהכרטיס (500px, בלי \"שם לקוח\", שם ברירת מחדל \"פגישה חודשית — {חודש}\"). קבצים: MeetingsPanel.tsx/.css (בלוק CSS אחד בסוף הקובץ בתוך .workspace-meetings-envelope), CreateMeetingDialog.tsx (רק כש-workspaceVariant && !isGlobal), SendSummaryUsersDialog.tsx (prop subtitle/workspaceVariant), Meeting.ts (+external_call_id), client.ts (localhost בלבד).",
     "need": "לעבור על ה-diff, למזג ל-stg, לוודא שהפריסה ל-Firebase עברה, ולסמן כאן \"נבנה\".\n\nמה כבר נבדק (מקומית מול הסטייג׳ינג, גבדור 105, יועץ ובעל העסק):\n• מדידת getComputedStyle של הציר והזירה מול הפרוטוטיפ (headless) — גבהים, גופנים, צבעים, ריפודים תואמים; מה שנשאר בדיף הוא רוחב החלון ותוכן מהשרת\n• ברירת המחדל בכניסה = הפגישה האחרונה שהתקיימה (לא \"לא התקיימה\")\n• יועץ: ממתין לאישורך / אושר ונשלח / לא התקיימה / עתידית — כל אחד עם הגוף והפוטר שלו; הנגן מנגן מהגלולה\n• בעל העסק: רק שלושה מצבים (#44), בלי שיחות (#45), בלי נגן, בלי טאבים לפני השליחה, \"הורדת הסיכום\" + \"הסיכום נשלח אליך בוואטסאפ בסיום הפגישה.\" אחרי השליחה\n• פופאפ הנמענים נפתח מ\"אישור ושליחת הסיכום בוואטסאפ\" ונמדד (420px, כותרת+תת-כותרת, שורות ממוסגרות, ראשי לפני \"ביטול\") — לא נשלח בפועל (#48 נשאר לבדיקה עם לקוח אמיתי)\n• \"+ תיאום פגישה\" נמדד (500px, \"תיאום פגישה\", \"{חברה} · פגישה חודשית קבועה\", \"מועד\", \"קביעת הפגישה\") — לא נוצרה פגישה\n• המסך הגלובלי של התקשורת לא נגע (הכל תחת .workspace-meetings-envelope ומחלקות וריאנט)\n• tsc --noEmit ו-eslint נקיים\nבדיקה (במקום #48, אישור ושליחה מהיועץ → הלקוח): היועץ מאשר ושולח; אצל הלקוח הצ׳יפ מתחלף ל\"הסיכום נשלח אליך\" וההודעה מגיעה בוואטסאפ.\nבדיקה (במקום #49, הורדת הסיכום אצל הלקוח): \"הורדת הסיכום\" מוריד את הסיכום המאושר.",
