     "kind": "check",
     "title": "למזג ‎PR #12‎ — מדדים: הגיליון, הכרטיס, הפוטר והעורך לפי הפרוטוטיפ",
     "what": "https://github.com/h-beehive/hk-client/pull/12 — ענף design/metrics-editor אל stg, עצמאי. שלושה קומיטים: העורך (1180px, שתי עמודות — #51/#101 מהסבב הקודם), התאמה ראשונה של הגיליון, והגיליון+הכרטיס במלואם: רצועה כהה עם גלולת טווח ופופאפ, עמודת מצב עם נקודה, שם נערך במקום, תאים = input תמיד עם Enter/חצים/Esc, כותרות חודש עם [+]/[−] ומפרידי 3px, השורה הריקה, פוטר עם גלולות ימי עבודה ו\"נשמר · HH:MM\", כרטיס המדד (600px: flag, בר 0–125% עם סמן ב-80%, יעד יומי, משפט הפער, מגמה 6 חודשים, \"שאל את העוזר\" → הצ׳אט עם השאלה), \"מחיקת המדד\" בפוטר העורך. קבצים: MetricsPanel.tsx/.css (בלוק CSS אחד לגיליון במקום הישן), WorkspacePanels.css (הדריסות הישנות הוסרו), WorkspaceAiChat.tsx (שאלה מ-location.state), client.ts (localhost בלבד).",
     "need": "לעבור על ה-diff, למזג ל-stg, לוודא שהפריסה ל-Firebase עברה, ולסמן כאן \"נבנה\".\n\nמה כבר נבדק (מקומית מול הסטייג׳ינג, גבדור 105 כמנהל תזרים, 13 מדדים אמיתיים):\n• מדידת getComputedStyle מול הפרוטוטיפ (headless) לגיליון, לכרטיס ולפופאפ הטווח — תואם; מה שנשאר הוא רוחב החלון ותוכן\n• שינוי שם מהגיליון נשמר בשרת (test123 → test123x → חזרה)\n• יעד מהתא + Enter נשמר, \"נשמר · 23:20\" בפוטר, הפוקוס ירד לשורה הבאה באותה עמודה; הוחזר ל-0\n• הכרטיס למדד לפי קטגוריות (0 מול 800,000): flag \"לא ביעד\", בר, \"0% מהיעד · יעד יומי 36,364 ₪\", \"חסר 800,000 ₪ … 36,364 ₪ בכל יום עבודה\", מגמה 6 חודשים עם קו יעד\n• \"שאל את העוזר על המדד\" → /chat עם השאלה מוכנה בשדה\n• העיפרון וצ׳יפ המקור פותחים את העורך; בפוטר \"מחיקת המדד\" (לא נמחק); שורה ריקה + Enter → העורך עם השם\n• tsc ו-eslint נקיים\n• לא נבדק: בעל העסק (אין לו סעיף מדדים בניווט), Sheets/חשבונאי (אין מדדים כאלה בגבדור — #52/#53)",
