     "what": "https://github.com/h-beehive/hk-client/pull/13 — ענף design/cashflow-ai אל stg, עצמאי. CSS חדש (src/pages/workspace/cashflowPicture/CashflowPictureDesign.css, מיובא אחרון ב-Workspace.tsx) ו-JSX ב-CashflowReportModal.tsx תחת workspaceVariant בלבד: הפס הכהה, גלולות הבקרות עם בוררים ו-✓, שינוי טווח בלי מחיקת הדוח (פס \"הטווח שונה\" + \"הפקה מחדש\"), טבלה ב-grid בלי גלילה אופקית ובלי עמודת חץ (חץ בתא הקטגוריה), אדום רק איפה שהפרוטוטיפ, דגל \"N% מהמחזור בתקופה\" בכותרת עלות המכר, פאנל 318px עם ראש נייבי ושאלה/תשובה בעיצוב הפרוטוטיפ, שליחה/ייצוא מהדוח המוצג בלי הפקה מחדש, פופאפ הנמענים בעיצוב המערכת. client.ts רק ל-localhost.",
     "need": "לעבור על ה-diff, למזג ל-stg, לוודא שהפריסה ל-Firebase עברה, ולסמן כאן \"נבנה\".\n\nמה כבר נבדק (מקומית מול הסטייג׳ינג, גבדור 105, מנהל תזרים ובעל העסק):\n• מדידת getComputedStyle מול הפרוטוטיפ (headless) — הפס, הבקרות, הכותרת, השורות, הגורמים והפאנל תואמים; ההבדלים שנשארו הם רוחב החלון\n• שינוי \"מ־\" → הפס \"הטווח שונה — … מאי 2026 – אוגוסט 2026\" + \"הפקה מחדש\" פועם, הטבלה נשארת, שדה השאלה פעיל → \"הפקה עכשיו\" → 4 חודשים, \"סה״כ / 4 חודשים\", הערת העוזר \"הדוח הופק מחדש — …\", פס ההקשר \"מאי–אוגוסט 2026\"\n• אין גלילה אופקית ב-4 חודשים (scrollWidth = clientWidth)\n• פירוט קטגוריה → גורמים; פירוט גורם → צ׳יפי תנועות \"dd.mm · שם · סכום\"\n• פופאפ השליחה (500px, מסוכם/מפורט/אקסל) נפתח ונסגר — לא נשלח\n• בעל העסק: \"שליחה לעצמי\", אין \"HK\" בטקסט, הפאנל פעיל; \"הפקה\" עדיין מוצג — לפי #79\n• tsc ו-eslint נקיים; המודל הישן (דשבורד/ריבוי חברות) לא נגע",
